<script setup lang="ts">
import {ref,reactive,onMounted,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import {state,t,l,fmt,api,wp,notify,loadData,refreshWorkspace,writeAccess,adminAccess,runAnalysis,activeJob} from '../state'
const route=useRoute(),router=useRouter(),tab=ref(String(route.query.tab||'sources')),adding=ref(false),busy=ref(false),research=ref<any[]>([]),researchQuery=ref(''),datasets=ref<any[]>([]),suggestions=ref<any[]>([]),materialOpen=ref(false),expandedRun=ref('')
const source=reactive({name:'',url:'',type:'rss',kind:'news',enabled:true,respect_robots:true,limit:12})
const settings=reactive({keywords:(state.workspace.settings.keywords||[]).join(', '),exclude:(state.workspace.settings.exclude_keywords||[]).join(', '),interval:state.workspace.settings.interval_minutes||360,threshold:state.workspace.settings.alert_threshold??80,min:state.workspace.settings.min_relevance??20,days:state.workspace.settings.lookback_days||30,automatic:state.workspace.settings.auto_monitor!==false})
const material=reactive({title:'',text:'',url:'',kind:'news',date:new Date().toISOString().slice(0,10)})
const availableSuggestions=computed(()=>suggestions.value.filter(s=>!state.sources.some(x=>x.url===s.url)))
const tabs=computed(()=>[{id:'sources',label:t('Monitoring sources','Источники мониторинга'),icon:'Radio'},{id:'research',label:t('Bank research','Обзоры банка'),icon:'BookOpen'},{id:'runs',label:t('Agent runs','Запуски агента'),icon:'Workflow'},{id:'materials',label:t('Materials & datasets','Материалы и данные'),icon:'Files'}])
watch(()=>route.query.tab,v=>{if(v)tab.value=String(v)})
onMounted(async()=>{try{[research.value,datasets.value,suggestions.value]=await Promise.all([api(wp('/research')),api(wp('/datasets')),api(wp('/source-suggestions'))])}catch(e:any){notify(e.message,true)}})
async function add(s:any=source){busy.value=true;try{await api(wp('/sources'),{method:'POST',body:s});adding.value=false;await loadData();notify(t('Source added. Run monitoring to check collection.','Источник добавлен. Запустите мониторинг для проверки.'))}catch(e:any){notify(e.message,true)}finally{busy.value=false}}
async function toggle(s:any){try{await api(wp('/sources/'+s.id),{method:'PATCH',body:{enabled:!s.enabled}});await loadData()}catch(e:any){notify(e.message,true)}}
async function remove(s:any){try{await api(wp('/sources/'+s.id),{method:'DELETE'});await loadData();notify(t('Source removed. Existing evidence is retained.','Источник удалён. Собранные материалы сохранены.'))}catch(e:any){notify(e.message,true)}}
async function save(){busy.value=true;try{const split=(x:string)=>x.split(',').map(x=>x.trim()).filter(Boolean);state.workspace=await api(wp('/settings'),{method:'PATCH',body:{keywords:split(settings.keywords),exclude_keywords:split(settings.exclude),interval_minutes:Number(settings.interval),alert_threshold:Number(settings.threshold),min_relevance:Number(settings.min),lookback_days:Number(settings.days),auto_monitor:settings.automatic}});notify(t('Monitoring preferences saved.','Настройки мониторинга сохранены.'))}catch(e:any){notify(e.message,true)}finally{busy.value=false}}
async function searchResearch(){try{research.value=await api(wp('/research?q='+encodeURIComponent(researchQuery.value)))}catch(e:any){notify(e.message,true)}}
async function retry(j:any){try{const r=await api(wp('/jobs/'+j.id+'/retry'),{method:'POST'});state.jobs=[r,...state.jobs];notify(t('Run queued for retry.','Повторный запуск поставлен в очередь.'))}catch(e:any){notify(e.message,true)}}
async function upload(ev:Event){const el=ev.target as HTMLInputElement,file=el.files?.[0];if(!file)return;busy.value=true;try{const f=new FormData();f.append('file',file);const r=await api(wp('/upload'),{method:'POST',body:f});if(r.kind?.includes('dataset')){datasets.value=await api(wp('/datasets'));notify(t('Dataset imported. Select a company to enrich the profile.','Данные импортированы. Выберите компанию для дополнения профиля.'));if(r.truncated)notify(t('Dataset imported with a 2,000-row preview limit.','Данные импортированы с лимитом 2 000 строк.'))}else{material.title=r.title;material.text=r.text;materialOpen.value=true;notify(t('Text extracted. Review it before adding to evidence.','Текст извлечён. Проверьте его перед добавлением.'))}}catch(e:any){notify(e.message,true)}finally{busy.value=false;el.value=''}}
async function addMaterial(){busy.value=true;try{await api(wp('/materials'),{method:'POST',body:{title:material.title,text:material.text,url:material.url,kind:material.kind,published_at:material.date?material.date+'T12:00:00Z':null}});materialOpen.value=false;material.title='';material.text='';research.value=await api(wp('/research'));notify(t('Material added. Run analysis to use it in your workspace.','Материал добавлен. Запустите анализ, чтобы использовать его.'))}catch(e:any){notify(e.message,true)}finally{busy.value=false}}
async function selectClient(d:any,ev:Event){const id=(ev.target as HTMLSelectElement).value;if(!id)return;try{state.workspace=await api(wp('/datasets/'+d.id+'/select'),{method:'POST',body:{company_id:id}});router.push('/company');notify(t('Client features loaded. Review the profile before confirming.','Признаки клиента загружены. Проверьте профиль перед подтверждением.'))}catch(e:any){notify(e.message,true)}}
</script>
<template><div class="page-heading"><div><span class="eyebrow">{{t('GOOD INTELLIGENCE STARTS HERE','ХОРОШАЯ АНАЛИТИКА НАЧИНАЕТСЯ ЗДЕСЬ')}}</span><h1>{{t('Your sources of clarity.','Ваши источники ясности.')}}</h1><p>{{t('Choose what to monitor. Follow every step from source to insight.','Выбирайте источники. Прослеживайте каждый шаг от факта до вывода.')}}</p></div><button v-if="writeAccess" class="btn primary" :disabled="!!activeJob" @click="runAnalysis"><Icon name="RefreshCw" :size="17"/>{{t('Run monitoring','Запустить мониторинг')}}</button></div><div class="tabs page-tabs"><button v-for="a in tabs" :key="a.id" :class="{active:tab===a.id}" @click="tab=a.id"><Icon :name="a.icon" :size="16"/>{{a.label}}</button></div>
<template v-if="tab==='sources'"><div class="sources-layout"><section><div class="section-heading"><h2>{{t('Connected sources','Подключённые источники')}} <span class="count-pill">{{state.sources.length}}</span></h2><button v-if="writeAccess" class="btn secondary small-btn" @click="adding=!adding"><Icon name="Plus" :size="15"/>{{t('Add source','Добавить источник')}}</button></div><form v-if="adding" class="card form-stack mb-lg" @submit.prevent="add()"><h3>{{t('Add a monitoring source','Добавить источник мониторинга')}}</h3><div class="form-grid"><label>{{t('Source name','Название')}}<input v-model="source.name" required></label><label>{{t('Source type','Тип источника')}}<select v-model="source.type"><option value="rss">RSS / Atom</option><option value="html">{{t('Web page','Веб-страница')}}</option></select></label><label class="span-2">URL<input v-model="source.url" type="url" required placeholder="https://example.com/feed.xml"></label><label>{{t('Material type','Тип материала')}}<select v-model="source.kind"><option value="news">{{t('External reporting','Новости')}}</option><option value="bank">{{t('Bank research','Аналитика банка')}}</option></select></label><label>{{t('Items per collection','Материалов за сбор')}}<input v-model="source.limit" type="number" min="1" max="30"></label></div><label class="checkbox-label"><input type="checkbox" v-model="source.respect_robots">{{t('Respect source robots.txt','Учитывать robots.txt источника')}}</label><div class="row gap-sm"><button class="btn primary" :disabled="busy">{{t('Connect source','Подключить источник')}}</button><button class="btn ghost" type="button" @click="adding=false">{{t('Cancel','Отмена')}}</button></div></form><div class="source-list"><article v-for="s in state.sources" :key="s.id" class="card source-card"><div class="source-top"><span class="source-mark"><Icon :name="s.type==='rss'?'Rss':'Globe2'" :size="22"/></span><div class="source-main"><h3>{{s.name}}</h3><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.url}}</a></div><button v-if="writeAccess" class="toggle" role="switch" :aria-checked="s.enabled" :class="{on:s.enabled}" @click="toggle(s)" :aria-label="t('Enable source','Включить источник')+' '+s.name"><i></i></button></div><div class="source-bottom"><span class="health-badge" :class="s.health"><span class="dot"></span>{{t({ok:'Collecting',error:'Needs attention',not_checked:'Not checked'}[s.health]||'Not checked',{ok:'Сбор работает',error:'Требует внимания',not_checked:'Не проверен'}[s.health]||'Не проверен')}}</span><span>{{s.type.toUpperCase()}} · {{s.kind==='bank'?t('Bank research','Аналитика банка'):t('News','Новости')}}</span><span v-if="s.last_checked">{{fmt(s.last_checked,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}} · {{s.last_count||0}} {{t('items','материалов')}}</span><button v-if="writeAccess" class="icon-btn" @click="remove(s)" :aria-label="t('Remove source','Удалить источник')+' '+s.name"><Icon name="Trash2" :size="15"/></button></div><p v-if="s.error" class="source-error"><Icon name="Info" :size="14"/>{{s.error}}</p></article><div v-if="!state.sources.length" class="card empty"><Icon name="Radio" :size="30"/><h3>{{t('Connect your first source','Подключите первый источник')}}</h3><p>{{t('Start with a suggestion below or add a trusted RSS feed or website.','Выберите предложенный источник или добавьте RSS и сайт.')}}</p></div></div><div class="section-heading mt-lg"><h3>{{t('Suggested for your context','Предложено для вашей компании')}}</h3><span class="small muted">{{t('Review before connecting','Проверьте перед подключением')}}</span></div><div class="suggestion-list"><article v-for="s in availableSuggestions" :key="s.url" class="suggestion-row"><Icon name="Radio" :size="19"/><div><strong>{{s.name}}</strong><p>{{l(s.reason)}}</p></div><button v-if="writeAccess" class="icon-btn" @click="add({...s,respect_robots:true})" :disabled="busy" :aria-label="t('Add source','Добавить источник')+' '+s.name"><Icon name="Plus" :size="17"/></button></article></div></section><aside class="card monitoring-settings"><div class="card-heading"><div><h2>{{t('Tune your radar','Настройте радар')}}</h2><p>{{t('Make the feed reflect your priorities.','Лента под ваши приоритеты.')}}</p></div><Icon name="SlidersHorizontal" :size="18"/></div><form @submit.prevent="save" class="form-stack"><label>{{t('Topics & keywords','Темы и ключи')}}<textarea v-model="settings.keywords" rows="4" :disabled="!adminAccess"></textarea><small>{{t('Separate with commas. Add company, competitor and exposure terms.','Разделяйте запятыми. Укажите компанию, конкурентов и факторы влияния.')}}</small></label><label>{{t('Exclude topics','Исключить темы')}}<textarea v-model="settings.exclude" rows="2" :disabled="!adminAccess" :placeholder="t('Unwanted phrases, separated by commas','Ненужные фразы через запятую')"></textarea></label><div class="form-divider"></div><label class="checkbox-label"><input v-model="settings.automatic" type="checkbox" :disabled="!adminAccess">{{t('Automatic monitoring','Автоматический мониторинг')}}</label><label>{{t('Collection frequency','Частота сбора')}}<select v-model="settings.interval" :disabled="!adminAccess"><option :value="30">{{t('Every 30 minutes','Каждые 30 минут')}}</option><option :value="60">{{t('Every hour','Каждый час')}}</option><option :value="360">{{t('Every 6 hours','Каждые 6 часов')}}</option><option :value="1440">{{t('Daily','Раз в сутки')}}</option></select></label><label>{{t('Alert threshold','Порог уведомления')}}<div class="range-row"><input v-model="settings.threshold" type="range" min="30" max="100" :disabled="!adminAccess"><strong>{{settings.threshold}}%</strong></div><small>{{t('Notify when business relevance reaches this score.','Уведомлять при достижении этой релевантности.')}}</small></label><div class="form-grid"><label>{{t('Min. relevance','Мин. релевантность')}}<input v-model="settings.min" type="number" min="0" max="100" :disabled="!adminAccess"></label><label>{{t('Lookback days','Глубина, дней')}}<input v-model="settings.days" type="number" min="1" max="90" :disabled="!adminAccess"></label></div><button v-if="adminAccess" class="btn primary full" :disabled="busy">{{t('Save monitoring setup','Сохранить настройки')}}</button><p v-else class="small muted">{{t('Workspace owners and admins manage monitoring rules.','Правила мониторинга настраивает владелец или администратор.')}}</p></form></aside></div></template>
<template v-else-if="tab==='research'"><div class="research-intro"><span class="bank-mark">A</span><div><h2>{{t('Alfa-Bank research library','Библиотека аналитики Альфа-Банка')}}</h2><p>{{t('Case-provided research is dated expert context. We retrieve relevant passages and keep them separate from current news and model interpretation.','Обзоры из кейса — датированный экспертный контекст. Мы находим релевантные фрагменты и отделяем их от текущих новостей и интерпретации модели.')}}</p></div><span class="badge neutral">{{research.length}} {{t('materials','материалов')}}</span></div><form class="search-filter-row" @submit.prevent="searchResearch"><label class="search-input"><Icon name="Search" :size="18"/><input v-model="researchQuery" :placeholder="t('Search bank research by a business question…','Поиск по бизнес-вопросу…')" :aria-label="t('Search bank research','Поиск аналитики банка')"></label><button class="btn secondary">{{t('Search','Найти')}}</button></form><div class="research-grid"><article v-for="b in research" :key="b.id" class="card research-card"><div class="row between"><span class="bank-tag">{{b.origin==='workspace_upload'?t('WORKSPACE MATERIAL','МАТЕРИАЛ ПРОСТРАНСТВА'):t('ALFA-BANK RESEARCH','АНАЛИТИКА АЛЬФА-БАНКА')}}</span><Icon name="FileText" :size="19"/></div><h3>{{b.title.replace('.pdf','').replaceAll('_',' ')}}</h3><p class="small muted">{{fmt(b.published_at,{dateStyle:'medium'})}} <span v-if="b.pages">· {{b.pages}} {{t('pages','стр.')}}</span><span v-if="b.page">· {{t('Page','Страница')}} {{b.page}}</span><span v-if="b.ocr"> · OCR</span></p><p class="research-preview">{{b.text||b.preview}}</p><a v-if="b.url" :href="b.url" target="_blank" rel="noopener noreferrer" class="text-link">{{t('View original document','Открыть оригинал')}}<Icon name="ExternalLink" :size="14"/></a><span class="research-note">{{t('Historical research · not a current bank recommendation','Исторический обзор · не текущая рекомендация банка')}}</span></article></div></template>
<template v-else-if="tab==='runs'"><div class="section-heading"><div><h2>{{t('From data to a defensible insight','От данных к обоснованному выводу')}}</h2><p class="muted small">{{t('Planning, tools, context and verification — visible at every step.','Планирование, инструменты, контекст и проверка — виден каждый шаг.')}}</p></div></div><article v-for="j in state.jobs" :key="j.id" class="card run-card"><button class="run-head" @click="expandedRun=expandedRun===j.id?'':j.id"><span class="stat-icon" :class="j.status==='failed'?'amber':'purple'"><Icon :name="j.kind==='brief'?'FileText':'Workflow'" :size="20"/></span><div><h3>{{t({website:'Company discovery',analyze:'Business-impact analysis',brief:'Executive brief'}[j.kind],{website:'Изучение компании',analyze:'Анализ влияния на бизнес',brief:'Бизнес-сводка'}[j.kind])}}</h3><span class="small muted">{{fmt(j.created_at,{dateStyle:'medium',timeStyle:'short'})}} · {{j.id.slice(0,8)}}</span></div><span class="status-badge" :class="j.status">{{t({queued:'Queued',running:'Running',completed:'Completed',failed:'Needs attention'}[j.status],{queued:'В очереди',running:'Выполняется',completed:'Завершён',failed:'Требует внимания'}[j.status])}}</span><Icon :name="expandedRun===j.id?'ChevronUp':'ChevronDown'" :size="17"/></button><div v-if="expandedRun===j.id" class="run-body"><p v-if="j.error" class="notice error-notice">{{j.error}}</p><div class="run-step" v-for="(s,i) in j.steps" :key="i"><span class="run-step-marker"><Icon :name="s.status==='error'?'AlertCircle':'Check'" :size="14"/></span><div><h4>{{s.name.replaceAll('_',' ')}}</h4><span class="small muted">{{s.tool||s.status}} · {{fmt(s.at,{timeStyle:'medium'})}}</span><details><summary>{{t('Inspect evidence & output','Доказательства и результат шага')}}</summary><pre>{{JSON.stringify(s,null,2)}}</pre></details></div></div><div class="row between mt-sm"><span class="small muted">{{j.result?.events!=null?j.result.events+' '+t('insights published','выводов опубликовано'):''}}</span><button v-if="j.status==='failed'&&writeAccess" class="btn secondary small-btn" @click="retry(j)"><Icon name="RotateCcw" :size="14"/>{{t('Retry run','Повторить запуск')}}</button></div></div></article><div v-if="!state.jobs.length" class="card empty"><Icon name="Workflow" :size="32"/><h3>{{t('Your analysis trail starts here.','Здесь начинается история анализа.')}}</h3><p>{{t('Run monitoring to inspect the agent’s plan, tools and verification checks.','Запустите мониторинг, чтобы увидеть план, инструменты и проверки агента.')}}</p></div></template>
<template v-else><div class="materials-grid"><section class="card"><span class="form-section-icon"><Icon name="FileUp" :size="25"/></span><h2>{{t('Add your own evidence','Добавьте свои материалы')}}</h2><p class="muted">{{t('Bring a news article, a bank report or case client data into this workspace. You review extracted text before it becomes evidence.','Добавьте новость, обзор банка или данные клиентов. Извлечённый текст можно проверить до добавления.')}}</p><label v-if="writeAccess" class="upload-area"><Icon :name="busy?'LoaderCircle':'Upload'" :class="{spin:busy}" :size="29"/><strong>{{t('Choose a file to upload','Выбрать файл')}}</strong><span>PDF · TXT · HTML · CSV · {{t('up to 10 MB','до 10 МБ')}}</span><input type="file" accept=".pdf,.txt,.md,.html,.csv" @change="upload" :disabled="busy" :aria-label="t('Upload evidence file','Загрузить файл')"></label><button v-if="writeAccess" class="btn secondary full mt-sm" @click="materialOpen=!materialOpen"><Icon name="ClipboardPaste" :size="16"/>{{t('Paste an article or research excerpt','Вставить текст новости или обзора')}}</button></section><section class="card"><h2>{{t('Case client datasets','Данные клиентов из кейса')}}</h2><p class="muted small">{{t('Import company and payment CSVs. Select an anonymised company to enrich industry, geography, bank product exposures and payment connections. Imports are limited to 2,000 rows per file.','Загрузите CSV компаний и платежей. Выбор обезличенного клиента дополнит отрасль, географию, банковские продукты и платёжные связи. До 2 000 строк на файл.')}}</p><article v-for="d in datasets" :key="d.id" class="dataset-card"><h4>{{d.filename}}</h4><p>{{d.row_count}} {{t('rows','строк')}} · {{d.columns.length}} {{t('fields','полей')}}</p><select v-if="d.kind==='client_dataset'&&writeAccess" @change="selectClient(d,$event)" :aria-label="t('Select case company','Выбрать компанию из кейса')"><option value="">{{t('Select a client to load…','Выберите клиента…')}}</option><option v-for="r in d.sample" :key="r.SYNTHETIC_U" :value="r.SYNTHETIC_U">{{r.SYNTHETIC_U}} · {{r.MAINOKVED_NAME}}</option></select><details><summary>{{t('Preview fields','Посмотреть поля')}}</summary><pre>{{JSON.stringify(d.sample.slice(0,2),null,2)}}</pre></details></article><div class="row gap-sm wrap mt-sm"><a :href="'/api'+wp('/case-sample/clients')" class="btn secondary small-btn"><Icon name="Download" :size="14"/>{{t('Case company sample','Образец компаний')}}</a><a :href="'/api'+wp('/case-sample/payments')" class="btn secondary small-btn"><Icon name="Download" :size="14"/>{{t('Payment sample','Образец платежей')}}</a></div><div v-if="!datasets.length" class="empty compact-empty"><Icon name="Database" :size="27"/><p>{{t('No datasets yet. Your company profile also works without a CSV.','Данных пока нет. Профиль компании работает и без CSV.')}}</p></div></section></div><form v-if="materialOpen" class="card form-stack mt-lg" @submit.prevent="addMaterial"><div class="card-heading"><h2>{{t('Review material','Проверьте материал')}}</h2><button type="button" class="icon-btn" @click="materialOpen=false" :aria-label="t('Close form','Закрыть форму')"><Icon name="X"/></button></div><div class="form-grid"><label>{{t('Title','Заголовок')}}<input v-model="material.title" required minlength="3"></label><label>{{t('Material type','Тип материала')}}<select v-model="material.kind"><option value="news">{{t('External reporting','Новости')}}</option><option value="bank">{{t('Bank research (user-attributed)','Обзор банка (указано вами)')}}</option></select></label><label>{{t('Original URL (optional)','Ссылка на оригинал (необязательно)')}}<input v-model="material.url" type="url"></label><label>{{t('Publication date','Дата публикации')}}<input v-model="material.date" type="date"></label><label class="span-2">{{t('Source text','Текст источника')}}<textarea v-model="material.text" rows="12" required minlength="60"></textarea></label></div><button class="btn primary" :disabled="busy">{{t('Add to workspace evidence','Добавить в материалы пространства')}}<Icon name="Check" :size="16"/></button></form></template>
</template>
